 fn cancel_empty_into<'r>(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.validate(effect)?;if self.typed.is_some(){return Err(invalid("record field cancellation retains initialized child"))}if self.storage.initialized(){let poll=self.storage.take_box_into(&mut self.typed,effect);return match poll{semio_framework_value_control_contract::RetainedWorkPoll::Complete(turn)=>Ok(reply.progress().complete(turn.result.map_err(Into::into))),semio_framework_value_control_contract::RetainedWorkPoll::Pending{..}=>Err(invalid("native record field cancellation unexpectedly suspended"))}}let turn=self.storage.release(effect);if self.storage.terminal_is_empty(){self.work=None}Ok(reply.progress().complete(turn.result.map_err(Into::into)))}
